        let remote = FakeRemote::new();
        cutover_revert(&remote, &cfg, &f, &f, "devtest-alpha", "r-alpha-new", "r-alpha", false).await;
        assert_eq!(f.calls(), ["rename r-alpha-new devtest-alpha-new", "rename r-alpha devtest-alpha"]);
